import pandas as pd
import json

# Load the fills data
try:
    df = pd.read_csv('blackbox_os/roles/data_scientist/workflows/mock_data/pipeline_runs/run_6/fills.csv')

    # Filter for BTC trades (assuming symbol column contains 'BTC')
    btc_trades = df[df['symbol'].str.contains('BTC')]

    if len(btc_trades) == 0:
        result = {'fraction': 0.0, 'amount': 0.0}
    else:
        # Calculate win rate and payoff ratio
        positive_pnl = btc_trades[btc_trades['realized_pnl'] > 0]['realized_pnl']
        negative_pnl = btc_trades[btc_trades['realized_pnl'] < 0]['realized_pnl']

        win_rate = len(positive_pnl) / len(btc_trades)
        avg_win = positive_pnl.mean() if len(positive_pnl) > 0 else 0
        avg_loss = abs(negative_pnl.mean()) if len(negative_pnl) > 0 else 0

        # Calculate Kelly fraction
        if avg_loss > 0 and avg_win > 0:
            payoff_ratio = avg_win / avg_loss
            kelly_fraction = (win_rate * payoff_ratio - (1 - win_rate)) / payoff_ratio
            kelly_fraction = max(0, min(kelly_fraction, 1))  # Bound between 0 and 1
        else:
            kelly_fraction = 0.0

        # Calculate dollar amount
        bankroll = 50000
        amount = kelly_fraction * bankroll

        result = {'fraction': float(kelly_fraction), 'amount': float(amount)}

except Exception as e:
    result = {'fraction': 0.0, 'amount': 0.0}

print(json.dumps(result))
